// Site search — command palette panel driven by FlexSearch.
// Index: /searchindex.json generated by layouts/home.searchindex.json.
// Originally based on https://github.com/frjo/hugo-theme-zen/blob/main/assets/js/search.js
import * as params from "@params";

(function () {
  "use strict";

  const panel = document.getElementById("search-panel");
  if (!panel) return;

  const triggers = document.querySelectorAll(".search-bar-button");
  const input = panel.querySelector(".search-text");
  const closeButtons = panel.querySelectorAll("[data-search-close]");
  const resultsEl = panel.querySelector(".search-results");
  const emptyEl = panel.querySelector(".search-empty");
  const loadingEl = panel.querySelector(".search-loading");
  const countEl = panel.querySelector(".search-count");

  const index = new FlexSearch.Document({
    document: {
      id: "id",
      index: ["title", "tags", "content", "date"],
      store: ["title", "summary", "date", "permalink"],
    },
    tokenize: "forward",
  });

  let ready = false;
  let activeIndex = -1;
  let debounceTimer = null;
  let lastTrigger = null;

  /* ── Index ─────────────────────────────────────────── */

  function buildIndex() {
    fetch(params.basePath + "searchindex.json")
      .then(function (response) {
        return response.json();
      })
      .then(function (data) {
        data.forEach(function (item) {
          index.add(item);
        });
        ready = true;
        loadingEl.hidden = true;
        if (!panel.hidden) refresh();
      })
      .catch(function () {
        ready = true;
        loadingEl.hidden = true;
      });
  }

  /* ── Rendering ─────────────────────────────────────── */

  function escapeHtml(s) {
    return s.replace(/[&<>"']/g, function (c) {
      return {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;",
      }[c];
    });
  }

  // Wrap query term occurrences in <mark>. Segments are escaped individually
  // before injection, so the markup is safe even for hostile index text.
  function highlight(text, terms) {
    if (!terms.length) return escapeHtml(text);
    const lower = text.toLowerCase();
    const marks = [];
    terms.forEach(function (term) {
      let idx = 0;
      while ((idx = lower.indexOf(term, idx)) !== -1) {
        marks.push([idx, idx + term.length]);
        idx += term.length;
      }
    });
    if (!marks.length) return escapeHtml(text);
    marks.sort(function (a, b) {
      return a[0] - b[0];
    });
    const merged = [];
    marks.forEach(function (m) {
      const last = merged[merged.length - 1];
      if (last && m[0] <= last[1]) {
        last[1] = Math.max(last[1], m[1]);
      } else {
        merged.push([m[0], m[1]]);
      }
    });
    let out = "";
    let cursor = 0;
    merged.forEach(function (m) {
      out += escapeHtml(text.slice(cursor, m[0]));
      out += "<mark>" + escapeHtml(text.slice(m[0], m[1])) + "</mark>";
      cursor = m[1];
    });
    return out + escapeHtml(text.slice(cursor));
  }

  function show(els) {
    els.forEach(function (el) {
      el.hidden = false;
    });
  }

  function hide(els) {
    els.forEach(function (el) {
      el.hidden = true;
    });
  }

  function resetResults() {
    activeIndex = -1;
    input.setAttribute("aria-activedescendant", "");
    countEl.textContent = "";
    hide([resultsEl, emptyEl]);
  }

  function renderEmpty(query) {
    activeIndex = -1;
    input.setAttribute("aria-activedescendant", "");
    countEl.textContent = "";
    emptyEl.textContent = emptyEl.dataset.noResults.replace("%s", query);
    hide([resultsEl]);
    show([emptyEl]);
  }

  function renderResults(items, terms) {
    activeIndex = -1;
    input.setAttribute("aria-activedescendant", "");
    resultsEl.textContent = "";
    hide([emptyEl]);

    const fragment = document.createDocumentFragment();
    items.forEach(function (item, i) {
      const li = document.createElement("li");
      li.className = "search-result";
      li.id = "search-result-" + i;
      li.setAttribute("role", "option");

      const a = document.createElement("a");
      a.href = item.permalink;

      const head = document.createElement("span");
      head.className = "search-result-head";

      const title = document.createElement("span");
      title.className = "search-result-title";
      title.innerHTML = highlight(item.title, terms);

      const date = document.createElement("time");
      date.className = "search-result-date";
      date.textContent = item.date;

      const summary = document.createElement("p");
      summary.className = "search-result-summary";
      summary.innerHTML = highlight(item.summary, terms);

      head.append(title, date);
      a.append(head, summary);
      li.appendChild(a);
      fragment.appendChild(li);
    });
    resultsEl.appendChild(fragment);

    const n = items.length;
    countEl.textContent =
      n +
      " " +
      (n === 1 ? countEl.dataset.countOne : countEl.dataset.countMany);
    show([resultsEl]);
  }

  function doSearch() {
    const q = input.value.trim();
    if (!q) {
      resetResults();
      return;
    }
    if (!ready) return;

    const results = index.search({
      query: q,
      enrich: true,
      limit: params.searchLimit,
    });
    const items = {};
    results.forEach(function (result) {
      result.result.forEach(function (r) {
        items[r.doc.permalink] = r.doc;
      });
    });
    const list = Object.values(items);
    const terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    if (list.length) {
      renderResults(list, terms);
    } else {
      renderEmpty(q);
    }
  }

  function refresh() {
    if (!ready) return;
    const q = input.value.trim();
    if (q) {
      doSearch();
    } else {
      resetResults();
    }
  }

  /* ── Keyboard navigation over results ──────────────── */

  function resultLinks() {
    return Array.from(resultsEl.querySelectorAll("a"));
  }

  function setActive(idx) {
    const links = resultLinks();
    if (!links.length) return;
    const max = links.length - 1;
    activeIndex = Math.max(0, Math.min(idx, max));
    const link = links[activeIndex];
    input.setAttribute("aria-activedescendant", link.closest("li").id);
    links.forEach(function (l) {
      l.closest("li").classList.toggle("is-active", l === link);
    });
  }

  function moveActive(step) {
    const links = resultLinks();
    if (!links.length) return;
    const max = links.length - 1;
    let next;
    if (activeIndex < 0) {
      next = step > 0 ? 0 : max;
    } else {
      next = activeIndex + step;
      if (next > max) next = 0;
      if (next < 0) next = max;
    }
    setActive(next);
    resultLinks()[activeIndex].scrollIntoView({ block: "nearest" });
  }

  function openActive() {
    const links = resultLinks();
    if (!links.length) return;
    const link = activeIndex >= 0 ? links[activeIndex] : links[0];
    close();
    link.click();
  }

  function onInputKeydown(e) {
    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        moveActive(1);
        break;
      case "ArrowUp":
        e.preventDefault();
        moveActive(-1);
        break;
      case "Enter":
        e.preventDefault();
        openActive();
        break;
      case "Tab": {
        // Trap focus inside the panel.
        const focusable = Array.from(
          panel.querySelectorAll("a[href], button"),
        ).filter(function (el) {
          return !el.hidden;
        });
        if (!focusable.length) return;
        const first = focusable[0];
        const last = focusable[focusable.length - 1];
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
        break;
      }
    }
  }

  // Escape closes the panel from anywhere inside it (capture phase).
  function onGlobalKeydown(e) {
    if (e.key !== "Escape") return;
    e.preventDefault();
    e.stopPropagation();
    close();
  }

  /* ── Open / close ──────────────────────────────────── */

  function open() {
    lastTrigger = document.activeElement;
    input.value = "";
    activeIndex = -1;
    panel.classList.remove("is-closing");
    panel.hidden = false;
    document.body.classList.add("search-open");
    document.addEventListener("keydown", onGlobalKeydown, true);
    triggers.forEach(function (t) {
      t.setAttribute("aria-expanded", "true");
    });
    if (ready) {
      loadingEl.hidden = true;
      resetResults();
    } else {
      hide([resultsEl, emptyEl]);
      loadingEl.hidden = false;
    }
    input.focus();
  }

  function close() {
    if (panel.hidden) return;
    panel.classList.add("is-closing");
    setTimeout(function () {
      panel.hidden = true;
      panel.classList.remove("is-closing");
      document.body.classList.remove("search-open");
      document.removeEventListener("keydown", onGlobalKeydown, true);
      triggers.forEach(function (t) {
        t.setAttribute("aria-expanded", "false");
      });
      if (lastTrigger) lastTrigger.focus();
    }, 120);
  }

  /* ── Bindings ──────────────────────────────────────── */

  triggers.forEach(function (t) {
    t.addEventListener("click", function () {
      open();
    });
  });

  closeButtons.forEach(function (el) {
    el.addEventListener("click", function (e) {
      e.preventDefault();
      close();
    });
  });

  input.addEventListener("input", function () {
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(doSearch, 120);
  });

  input.addEventListener("keydown", onInputKeydown);

  // Hovering a result mirrors the active item.
  resultsEl.addEventListener("mouseover", function (e) {
    const li = e.target.closest(".search-result");
    if (!li) return;
    setActive(Array.from(resultsEl.children).indexOf(li));
  });

  buildIndex();
})();
